<?php
declare(strict_types=1);
namespace Zandu\Tests\Modules\CashManagement\Domain;
use DateTimeImmutable;use PHPUnit\Framework\TestCase;use Zandu\Modules\CashManagement\Domain\CashMovement\{CashMovement,CashMovementType};use Zandu\Platform\Decimal\BrickDecimalFactory;use Zandu\Platform\Identity\SymfonyUuidFactory;use Zandu\SharedKernel\Identity\{ActorId,CashMovementId,CashSessionId,OrganizationId,StoreId};use Zandu\SharedKernel\Money\{Currency,Money};
final class CashMovementTest extends TestCase{public function testPositiveManualMovement():void{$f=new SymfonyUuidFactory();$m=CashMovement::record(CashMovementId::fromString('0198d701-1111-7111-8111-111111111111',$f),OrganizationId::fromString('0198d702-1111-7111-8111-111111111111',$f),StoreId::fromString('0198d703-1111-7111-8111-111111111111',$f),CashSessionId::fromString('0198d704-1111-7111-8111-111111111111',$f),CashMovementType::CashIn,Money::fromString('10',Currency::fromCode('XAF'),new BrickDecimalFactory()),null,'Deposit',ActorId::fromString('0198d705-1111-7111-8111-111111111111',$f),null,new DateTimeImmutable());self::assertTrue($m->type()->isIn());self::assertSame('10',$m->amount()->amount()->toString());}
public function testCashOutAndWithdrawalKeepDistinctTypes():void{$f=new SymfonyUuidFactory();$money=Money::fromString('5',Currency::fromCode('XAF'),new BrickDecimalFactory());$actor=ActorId::fromString('0198d70f-1111-7111-8111-111111111111',$f);$common=[OrganizationId::fromString('0198d706-1111-7111-8111-111111111111',$f),StoreId::fromString('0198d707-1111-7111-8111-111111111111',$f),CashSessionId::fromString('0198d708-1111-7111-8111-111111111111',$f),$money];$out=CashMovement::record(CashMovementId::fromString('0198d709-1111-7111-8111-111111111111',$f),$common[0],$common[1],$common[2],CashMovementType::CashOut,$common[3],null,'Expense',$actor,null,new DateTimeImmutable());$withdrawal=CashMovement::record(CashMovementId::fromString('0198d70a-1111-7111-8111-111111111111',$f),$common[0],$common[1],$common[2],CashMovementType::CashWithdrawal,$common[3],null,'Bank deposit',$actor,null,new DateTimeImmutable());self::assertSame(CashMovementType::CashOut,$out->type());self::assertSame(CashMovementType::CashWithdrawal,$withdrawal->type());}
public function testZeroAmountIsRejected():void{$f=new SymfonyUuidFactory();$this->expectException(\InvalidArgumentException::class);CashMovement::record(CashMovementId::fromString('0198d70b-1111-7111-8111-111111111111',$f),OrganizationId::fromString('0198d70c-1111-7111-8111-111111111111',$f),StoreId::fromString('0198d70d-1111-7111-8111-111111111111',$f),CashSessionId::fromString('0198d70e-1111-7111-8111-111111111111',$f),CashMovementType::CashIn,Money::fromString('0',Currency::fromCode('XAF'),new BrickDecimalFactory()),null,null,ActorId::fromString('0198d70f-1111-7111-8111-111111111111',$f),null,new DateTimeImmutable());}}
